<body>

<div class="container">
    <header>
        <h1>Cram Drill</h1>
        <div class="nav-btns">
            <button id="nav-manage" class="active" onclick="switchView('manage')">Manage Deck</button>
            <button id="nav-study" onclick="switchView('study')">Cram Mode</button>
        </div>
    </header>

    <div id="view-manage" class="view active">
        <h2 class="section-title" style="margin-top:0">Add Single Card</h2>
        <div class="input-group">
            <input type="text" id="card-front" placeholder="Front (Question/Term)">
            <input type="text" id="card-back" placeholder="Back (Answer/Definition)">
            <button class="btn" onclick="addCard()">Add Card</button>
        </div>

        <h2 class="section-title">Bulk Paste Notes</h2>
        <p style="margin-bottom: 0.5rem; font-size: 0.9rem; color: var(--text-light);">Format: <code>Front | Back</code> (One card per line)</p>
        <div class="input-group">
            <textarea id="bulk-input" placeholder="Mitochondria | Powerhouse of the cell&#10;H2O | Water"></textarea>
        </div>
        <button class="btn btn-outline" onclick="bulkImport()">Import Notes</button>

        <h2 class="section-title">Your Deck (<span id="deck-count">0</span> cards)</h2>
        <div class="card-list" id="card-list">
            </div>

        <div class="actions-bar">
            <button class="btn btn-outline" onclick="exportDeck()">↓ Export JSON</button>
            <input type="file" id="import-file" style="display: none" accept=".json" onchange="importDeck(event)">
            <button class="btn btn-outline" onclick="document.getElementById('import-file').click()">↑ Import JSON</button>
            <button class="btn btn-danger" style="margin-left: auto;" onclick="clearDeck()">Clear Deck</button>
        </div>
    </div>

    <div id="view-study" class="view">
        <div id="study-active" class="hidden">
            <div class="progress" id="study-progress">Cards remaining: 0</div>

            <div class="flashcard-container" onclick="flipCard()">
                <div class="flashcard" id="active-card">
                    <div class="card-face card-front" id="card-front-display">Front</div>
                    <div class="card-face card-back" id="card-back-display">Back</div>
                </div>
            </div>

            <div class="study-controls" id="pre-flip-controls">
                <button class="btn" onclick="flipCard()">Show Answer</button>
            </div>

            <div class="study-controls hidden" id="post-flip-controls">
                <button class="btn btn-danger" onclick="markCard('hard')">Hard (Review again)</button>
                <button class="btn btn-success" onclick="markCard('easy')">Easy (Got it)</button>
            </div>
        </div>

        <div id="study-empty" class="hidden" style="text-align: center; padding: 3rem 0;">
            <h2 style="margin-bottom: 1rem;">Deck Complete! 🎉</h2>
            <p style="color: var(--text-light); margin-bottom: 2rem;">You've reviewed all cards in your queue.</p>
            <button class="btn" onclick="startStudy()">Restart Cram Drill</button>
        </div>

