            <p>Your deck is empty. Add cards in the Manage tab first.</p>
        </div>
    </div>
</div>

<script>
    let deck = JSON.parse(localStorage.getItem('cramDeck')) || [];
    let studyQueue = [];
    let currentCardIndex = 0;
    let isFlipped = false;

    // Initialize
    renderList();

    function saveDeck() {
        localStorage.setItem('cramDeck', JSON.stringify(deck));
        renderList();
    }

    // View Routing
    function switchView(viewName) {
        document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
        document.querySelectorAll('.nav-btns button').forEach(b => b.classList.remove('active'));

        document.getElementById(`view-${viewName}`).classList.add('active');
        document.getElementById(`nav-${viewName}`).classList.add('active');

        if (viewName === 'study') {
            startStudy();
        }
    }

    // --- Deck Management ---
    function addCard() {
        const front = document.getElementById('card-front').value.trim();
        const back = document.getElementById('card-back').value.trim();

        if (!front || !back) return alert('Both Front and Back are required.');

        deck.push({ id: Date.now().toString(), front, back });

        document.getElementById('card-front').value = '';
        document.getElementById('card-back').value = '';
        saveDeck();
    }

    function bulkImport() {
        const text = document.getElementById('bulk-input').value;
        const lines = text.split('\n');
        let added = 0;

        lines.forEach(line => {
            const parts = line.split('|');
            if (parts.length === 2) {
                const front = parts[0].trim();
                const back = parts[1].trim();
                if (front && back) {
                    deck.push({ id: Date.now().toString() + Math.random().toString(), front, back });
                    added++;
                }
            }
        });

        document.getElementById('bulk-input').value = '';
        saveDeck();
        alert(`Imported ${added} cards.`);
    }

    function deleteCard(id) {
        deck = deck.filter(c => c.id !== id);
        saveDeck();
    }

    function clearDeck() {
        if (confirm('Are you sure you want to delete all cards?')) {
            deck = [];
            saveDeck();
        }
    }

    function renderList() {
        const list = document.getElementById('card-list');
        document.getElementById('deck-count').innerText = deck.length;
        list.innerHTML = '';

        deck.forEach(card => {
            const div = document.createElement('div');
            div.className = 'list-item';
            div.innerHTML = `
                <div class="list-item-content">
                    <strong>${card.front}</strong>
                    <span style="color: #666; font-size: 0.9rem;">${card.back}</span>
                </div>
                <button class="btn btn-outline" style="padding: 0.4rem 0.8rem; color: var(--danger); border-color: var(--danger);" onclick="deleteCard('${card.id}')">Delete</button>
            `;
            list.appendChild(div);
        });
    }

    // --- Export / Import ---
    function exportDeck() {
        if(deck.length === 0) return alert("Deck is empty.");
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(deck));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", "cram_drill_deck.json");
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
    }

    function importDeck(event) {
        const file = event.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = function(e) {
            try {
                const imported = JSON.parse(e.target.result);
                if (Array.isArray(imported)) {
                    deck = deck.concat(imported);
                    saveDeck();
                    alert("Deck imported successfully!");
                }
            } catch (err) {
                alert("Invalid JSON file.");
            }
        };
        reader.readAsText(file);
        event.target.value = ''; // reset input
    }

    // --- Study Mode ---
    function startStudy() {
        const activeContainer = document.getElementById('study-active');
        const emptyContainer = document.getElementById('study-empty');
        const noCardsContainer = document.getElementById('study-no-cards');

        if (deck.length === 0) {
            activeContainer.classList.add('hidden');
            emptyContainer.classList.add('hidden');
            noCardsContainer.classList.remove('hidden');
            return;
        }

        noCardsContainer.classList.add('hidden');
        emptyContainer.classList.add('hidden');
        activeContainer.classList.remove('hidden');

        // Create a randomized copy of the deck for the cram queue
        studyQueue = [...deck].sort(() => Math.random() - 0.5);
        loadNextCard();
    }

    function loadNextCard() {
        if (studyQueue.length === 0) {
            document.getElementById('study-active').classList.add('hidden');
            document.getElementById('study-empty').classList.remove('hidden');
            return;
        }

        isFlipped = false;
        document.getElementById('active-card').classList.remove('is-flipped');

        const card = studyQueue[0];
        document.getElementById('card-front-display').innerText = card.front;
        document.getElementById('card-back-display').innerText = card.back;
        document.getElementById('study-progress').innerText = `Cards remaining: ${studyQueue.length}`;

        document.getElementById('pre-flip-controls').classList.remove('hidden');
        document.getElementById('post-flip-controls').classList.add('hidden');
    }

    function flipCard() {
        if(isFlipped) return; // Prevent double trigger
        isFlipped = true;
        document.getElementById('active-card').classList.add('is-flipped');
        document.getElementById('pre-flip-controls').classList.add('hidden');

        // Slight delay so controls don't appear before animation finishes
        setTimeout(() => {
            document.getElementById('post-flip-controls').classList.remove('hidden');
        }, 150);
    }

    function markCard(difficulty) {
        const card = studyQueue.shift(); // Remove from front

        if (difficulty === 'hard') {
            // Put it near the middle/end of the queue to see it again soon
            const insertIndex = Math.max(1, Math.floor(studyQueue.length / 2) + Math.floor(Math.random() * 2));
            studyQueue.splice(insertIndex, 0, card);
        }
        // If 'easy', it stays removed from the current cram queue

        loadNextCard();
    }
</script>

</body>
</html>

